'use client';

import { Suspense } from 'react';
import { useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Check, Loader2, AlertCircle } from 'lucide-react';

const PAYMENT_LABELS: Record<string, string> = {
  paid:         'Confirmed ✓',
  pending:      'Processing…',
  failed:       'Failed',
  not_required: 'Not Required',
  unpaid:       'Pending',
  refunded:     'Refunded',
};

const STATUS_LABELS: Record<string, string> = {
  draft:                            'Draft',
  pending_review:                   'Pending Review',
  admin_review:                     'Pending Admin Review',
  campaign_preparation_requested:   'Campaign Preparing',
  campaign_prepared:                'Campaign Prepared',
  awaiting_user_approval:           'Awaiting Your Approval',
  google_ads_verified:              'Google Ads Verified',
  google_ads_verification_failed:   'Verification Failed',
  pending_google_ads_manual_review: 'Manual Review',
  approved:                         'Approved',
  scheduled:                        'Scheduled',
  live:                             'Live',
  monitoring:                       'Monitoring',
  completed:                        'Completed',
  report_ready:                     'Report Ready',
  cancelled:                        'Cancelled',
};

const PAYMENT_COLOR: Record<string, string> = {
  paid:         'text-green-400',
  not_required: 'text-blue-400',
  pending:      'text-amber-400',
  failed:       'text-red-400',
  unpaid:       'text-neutral-400',
  refunded:     'text-neutral-400',
};

function AdoptionSuccessContent() {
  const searchParams = useSearchParams();
  const adoptionId = searchParams.get('adoption_id');
  const sessionId = searchParams.get('session_id');

  const [status, setStatus] = useState<'loading' | 'success' | 'error'>('loading');
  const [errorMsg, setErrorMsg] = useState('');
  const [adoption, setAdoption] = useState<any>(null);

  useEffect(() => {
    if (!adoptionId) {
      setStatus('error');
      setErrorMsg('Missing adoption ID.');
      return;
    }

    async function confirm() {
      try {
        if (sessionId) {
          const res = await fetch(`/api/adoptions/${adoptionId}/confirm/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ session_id: sessionId }),
          });

          const payload = await res.json();
          if (!res.ok || !payload?.verified) {
            throw new Error(payload?.reason || 'Payment could not be verified.');
          }
        }

        // Fetch real adoption record regardless of session_id path.
        const adoptionRes = await fetch(`/api/adoptions/${adoptionId}`);
        if (adoptionRes.ok) {
          setAdoption(await adoptionRes.json());
        }

        setStatus('success');
      } catch (err: any) {
        setErrorMsg(err?.message || 'Failed to confirm payment.');
        setStatus('error');
      }
    }

    confirm();
  }, [adoptionId, sessionId]);

  if (status === 'loading') {
    return (
      <div className="min-h-screen bg-neutral-950 flex items-center justify-center">
        <div className="text-center space-y-4">
          <Loader2 className="w-10 h-10 text-amber-400 animate-spin mx-auto" />
          <p className="text-neutral-400">Confirming your payment…</p>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className="min-h-screen bg-neutral-950 flex items-center justify-center">
        <div className="text-center space-y-4 max-w-md">
          <AlertCircle className="w-12 h-12 text-red-400 mx-auto" />
          <h2 className="text-xl font-semibold text-neutral-100">Something went wrong</h2>
          <p className="text-neutral-400">{errorMsg}</p>
          <p className="text-sm text-neutral-500">
            Your card may have been charged. Please contact us at{' '}
            <a href="mailto:support@sufipulse.com" className="text-amber-400 hover:underline">
              support@sufipulse.com
            </a>{' '}
            with your adoption ID: <span className="font-mono text-neutral-300">{adoptionId}</span>
          </p>
          <Link href="/">
            <button className="mt-4 px-6 py-2 bg-neutral-800 text-neutral-200 rounded-lg hover:bg-neutral-700 transition">
              Return Home
            </button>
          </Link>
        </div>
      </div>
    );
  }

  const paymentStatus = adoption?.paymentStatus ?? 'paid';
  const adoptionStatus = adoption?.adoptionStatus ?? 'admin_review';
  const isGoogleAds = adoption?.methodType === 'use_my_google_ads';

  const title = isGoogleAds ? 'Campaign Request Submitted' : 'Adoption Complete';
  const description = isGoogleAds
    ? 'Your Google Ads account is connected. Campaign structure will be prepared by SufiPulse and launched after admin review — typically 1–2 business days.'
    : 'May your contribution bring ease and contemplation to whoever discovers this kalam. Your sponsorship has been recorded and payment confirmed.';

  return (
    <div className="min-h-screen bg-neutral-950 flex items-center justify-center">
      <div className="max-w-lg w-full mx-4 text-center space-y-6">
        <div className="w-24 h-24 mx-auto bg-green-500/10 border border-green-500/20 rounded-full flex items-center justify-center">
          <Check className="w-10 h-10 text-green-500" />
        </div>

        <div>
          <h1 className="text-3xl font-serif font-light text-neutral-100 mb-3">{title}</h1>
          <p className="text-neutral-400 leading-relaxed">{description}</p>
        </div>

        <div className="bg-neutral-900 border border-neutral-800 rounded-xl p-6 text-left space-y-3">
          {!isGoogleAds && (
            <div className="flex justify-between text-sm">
              <span className="text-neutral-500">Payment</span>
              <span className={`font-medium ${PAYMENT_COLOR[paymentStatus] ?? 'text-neutral-300'}`}>
                {PAYMENT_LABELS[paymentStatus] ?? paymentStatus}
              </span>
            </div>
          )}
          <div className="flex justify-between text-sm">
            <span className="text-neutral-500">Adoption Status</span>
            <span className="text-amber-400 font-medium">
              {STATUS_LABELS[adoptionStatus] ?? adoptionStatus}
            </span>
          </div>
          {adoption?.amountPaid > 0 && (
            <div className="flex justify-between text-sm">
              <span className="text-neutral-500">Amount Paid</span>
              <span className="text-neutral-300 font-medium">${adoption.amountPaid}</span>
            </div>
          )}
          {adoption?.releaseTitle && (
            <div className="flex justify-between text-sm">
              <span className="text-neutral-500">Song</span>
              <span className="text-neutral-300 truncate max-w-[60%]">{adoption.releaseTitle}</span>
            </div>
          )}
          <div className="flex justify-between text-sm">
            <span className="text-neutral-500">Reference ID</span>
            <span className="text-neutral-300 font-mono text-xs">{adoptionId}</span>
          </div>
        </div>

        <p className="text-sm text-neutral-500">
          You will receive a confirmation email once the campaign is approved and
          launched. Typically within 1–2 business days.
        </p>

        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          {adoptionId && (
            <Link href={`/adopt-song/request/${adoptionId}`}>
              <button className="px-8 py-3 bg-amber-600 hover:bg-amber-700 text-white font-medium rounded-xl transition-colors w-full sm:w-auto">
                Track My Sponsorship
              </button>
            </Link>
          )}
          <Link href="/">
            <button className="px-8 py-3 bg-neutral-800 hover:bg-neutral-700 text-neutral-200 font-medium rounded-xl transition-colors w-full sm:w-auto">
              Return Home
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
}

export default function AdoptionSuccessPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-neutral-950 flex items-center justify-center">
          <div className="text-center space-y-4">
            <Loader2 className="w-10 h-10 text-amber-400 animate-spin mx-auto" />
            <p className="text-neutral-400">Loading…</p>
          </div>
        </div>
      }
    >
      <AdoptionSuccessContent />
    </Suspense>
  );
}
